	{
		this.varbValue = varbValue;
		this.projectileId = -1;
		this.displayName = displayName;
		this.levelRequired = levelRequired;
		this.baseMaxHit = baseMaxHit;
		this.spellbook = spellbook;
		this.element = element;
	}

