	description = "Displays current max hit",
	enabledByDefault = true,
	tags = {"max, hit, spec, pvp, magic, spell, combat, gear"}
)

@Slf4j
public class MaxHitPlugin extends Plugin
{

	private static final int WEAPON_SPECIAL_REQS = 906;
