{
	private static final Set<MagicSpell> GOD_SPELLS = ImmutableSet.of(
		MagicSpell.FLAMES_OF_ZAMORAK,
		MagicSpell.SARADOMIN_STRIKE,
		MagicSpell.CLAWS_OF_GUTHIX);

	private static final Set<MagicSpell> BOLT_SPELLS = ImmutableSet.of(
		MagicSpell.WIND_BOLT,
		MagicSpell.WATER_BOLT,
		MagicSpell.EARTH_BOLT,
		MagicSpell.FIRE_BOLT);

	private static final Set<Integer> STANDARD_SPELLBOOK_STAVES = ImmutableSet.of(
		ItemID.SMOKE_BATTLESTAFF,
		ItemID.MYSTIC_SMOKE_BATTLESTAFF,
		ItemID.TWINFLAME_STAFF
	);

	private static final Set<String> TWINFLAME_SPELLS = ImmutableSet.of(
		"Bolt",
		"Blast",
		"Wave"
	);

	private static final Set<Integer> TUMEKEN_SHADOWS = ImmutableSet.of(
		ItemID.TUMEKENS_SHADOW,
		ItemID.TUMEKENS_SHADOW_UNCHARGED
	);

	MagicSpell activeSpell = null;
	private double baseSpellDamage;
	private double elementalAmuletBonus;
	private double baseDamageModifier;
	private double primaryMagicDamage;
	private double preHitRoll;
	private double shadowBonus;
	private double standardSpellbookStaffBonus;
	private double virtusBonus;
	private double elementalWeakness;
	private double sceptreBonus;
	private double accursedSceptreSpecialAttackBonus;
	private double tomeBonus;
	private double markOfDarknessBonus;
	private double ahrimsDamnedBonus;
	//Ignore castle wars bracelet for now

	protected MagicMaxHitCalculator(MaxHitPlugin plugin, Client client, ItemManager itemManager, AttackStyle attackStyle)
	{
		super(plugin, client, itemManager, Skill.MAGIC, attackStyle);
		reset();
	}

	protected void reset()
	{
		super.reset();
		voidBonus = 0.0;
		baseSpellDamage = 0.0;
		baseDamageModifier = 0.0;
		primaryMagicDamage = 0.0;
		shadowBonus = 1.0;
		standardSpellbookStaffBonus = 0.0;
		virtusBonus = 0.0;
		prayerBonus = 0.0;
		elementalWeakness = 0.0;
		sceptreBonus = 0.0;
		accursedSceptreSpecialAttackBonus = 0.0;
		tomeBonus = 0.0;
		markOfDarknessBonus = 0.0;
		ahrimsDamnedBonus = 0.0;
	}

	@Override
	protected void updateEffectiveStrength()
	{
	}

	@Override
	protected void updateStyleBonus()
	{
	}

	private boolean chaosGauntletsEquipped()
	{
		return EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.GLOVES, ItemID.GAUNTLETS_OF_CHAOS);
	}

	private void getElementalAmuletBonus()
	{
		// Skip if not using standard spellbook
		if (!MagicSpell.getStandardSpells().contains(activeSpell))
		{
			elementalAmuletBonus = 0.0;
			return;
		}

		for (ElementalAmulet amulet : ElementalAmulet.values())
		{
			if (!EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.AMULET, amulet.getItemId()))
			{
				continue;
			}
			if (Arrays.asList(amulet.getElements()).contains(activeSpell.getElement()))
			{
				elementalAmuletBonus = 2.0;
				return;
			}
		}
		elementalAmuletBonus = 0.0;
	}

	public void getDragonbaneBonus()
	{
		// Check if opponent is draconic
		int npcId = getNpcId();

		if (npcId == -1)
			return;

		if (!DraconicMonsters.ID_LIST.contains(npcId))
		{
			return;
		}

		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.DRAGONHUNTER_WAND))
		{
			dragonbaneBonus = 1.4;
		}
	}

	private boolean matchingGodCapeEquipped()
	{
		for (GodCape cape : GodCape.values())
		{
			if (cape.isEquipped(equippedItems) && activeSpell.getVarbValue() == cape.getSpellId())
			{
				return true;
			}
		}
		return false;
	}

	private void getMagicDartBaseMaxDamage()
	{
		int magicLevel = client.getBoostedSkillLevel(Skill.MAGIC);

		// Check if opponent is in slayer task
		NPC npc = (NPC) opponent;

		boolean attackingTask = false;

		if (npc == null)
		{
			attackingTask = false;
		}
		else if (plugin.isTarget(npc))
		{
			attackingTask = true;
		}

		if (attackingTask && EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.SLAYER_STAFF_ENCHANTED))
		{
			baseSpellDamage = Math.floor(magicLevel / 6.0) + 13.0;
		}
		else
		{
			baseSpellDamage = Math.floor(magicLevel * 0.1) + 10.0;
		}
	}

	private void getSpellBaseMaxDamage()
	{
		// Powered Staves
		for (PoweredStaff staff : PoweredStaff.values())
		{
			for (int itemId : staff.getVarients())
			{
				if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, itemId))
				{
					baseSpellDamage = staff.getBaseMaxHit(effectiveLevel);
					return;
				}
			}
		}


		if (this.plugin.getActiveSpell() != null)
		{
			activeSpell = this.plugin.getActiveSpell();
		}
		else
		{
			int activeSpellVarbit = client.getVarbitValue(VarbitID.AUTOCAST_SPELL);

			// Spellbook Spells
			for (MagicSpell spell : MagicSpell.values())
			{
				if (activeSpellVarbit != spell.getVarbValue())
				{
					continue;
				}

				activeSpell = spell;
				break;
			}
		}

		if (activeSpell == null)
		{
			baseSpellDamage = 0.0;
			return;
		}

		// Magic Dart
		if (activeSpell == MagicSpell.MAGIC_DART)
		{
			getMagicDartBaseMaxDamage();
			return;
		}

		baseSpellDamage = activeSpell.getBaseMaxHit(client);
	}

	private void getBaseDamageModifier()
	{
		getSpellBaseMaxDamage();
		getElementalAmuletBonus();

		baseDamageModifier = baseSpellDamage;

		baseDamageModifier += elementalAmuletBonus;

		// Check for Chaos Gauntlets with bolt spells
		if (BOLT_SPELLS.contains(activeSpell))
		{
			if (chaosGauntletsEquipped())
			{
				baseDamageModifier += 3.0;
				return;
			}
		}

		// Check if a god spell is active
		if (!GOD_SPELLS.contains(activeSpell))
		{
			return;
		}
		// Check if a matching cape is equipped
		if (!matchingGodCapeEquipped())
		{
			return;
		}
		// Check if charge is active
		if (client.getVarbitValue(VarPlayerID.MAGEARENA_CHARGE) == 0)
		{
			return;
		}
		baseDamageModifier += 10.0;
	}

	private void getShadowBonus()
	{
		boolean shadowEquipped = false;
		// Check if Shadow equipped
		for (int staffId : TUMEKEN_SHADOWS)
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, staffId))
			{
				shadowEquipped = true;
			}
		}

		if (!shadowEquipped)
		{
			return;
		}

		int region = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
		boolean toaInside = TOA_ROOM_IDS.contains(region);
		if (toaInside)
		{
			shadowBonus = 4.0;
		}
		else
		{
			shadowBonus = 3.0;
		}
	}

	private void getSmokeBattlestaffBonus()
	{
		if (!Spellbook.STANDARD.isActive(client))
		{
			return;
		}

		for (int battlestaffId : STANDARD_SPELLBOOK_STAVES)
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, battlestaffId))
			{
				standardSpellbookStaffBonus = 0.1;
				return;
			}
		}
	}

	private void getVirtusBonus()
	{
		if (!Spellbook.ANCIENT.isActive(client))
		{
			virtusBonus = 0.0;
			return;
		}
		// Count how many pieces are equipped and multiply by the bonus per piece.
		long piecesEquipped = Arrays.stream(VirtusPieces.values())
			.filter(piece -> piece.isEquipped(equippedItems))
			.count();
		virtusBonus = piecesEquipped * 0.03;
	}

	private void getElementalWeakness()
	{
		for (MonsterWeaknesses monster : MonsterWeaknesses.values())
		{
			if (monster.hasWeakness(opponent, activeSpell))
			{
				elementalWeakness += monster.getSeverity();
				return;
			}

		}
	}

	private void getPrimaryMagicDamage()
	{
		updateStrengthBonus(); // I.E. visible bonuses
		getShadowBonus();
		updateVoidBonus();
		getAvariceBonus();
		getSalveBonus();
		getSlayerBonus();

		avariceBonus -= 1.0;
		salveBonus -= 1.0;

		getAvariceBonus();
		getSmokeBattlestaffBonus();
		getVirtusBonus();
		updatePrayerBonus();
		getElementalWeakness();
		double tempBonuses = (strengthBonus - voidBonus) * shadowBonus;
		tempBonuses = Math.min(1.0, tempBonuses);
		double totalBonus = voidBonus + salveBonus + avariceBonus + standardSpellbookStaffBonus + virtusBonus + prayerBonus;
		primaryMagicDamage = Math.floor(baseDamageModifier * (1 + tempBonuses + totalBonus));
	}

	private void getPreHitRoll()
	{
		// Slayer helm and salve/avarice don't stack
		if (salveBonus == 0.0 && avariceBonus == 0.0)
		{
			getSlayerBonus();
		}
		getDragonbaneBonus();
		//TODO: Add sceptre and tome bonus
		double totalSlayerBonus     = slayerBonus;
		double totalDragonbaneBonus = dragonbaneBonus;
		double totalSceptreBonus    = 1.0 + sceptreBonus;
		double totalAccursedBonus   = 1.0 + accursedSceptreSpecialAttackBonus;
		double totalTomeBonus       = 1.0 + tomeBonus;

		double slayerCalculation     = Math.floor(primaryMagicDamage    * totalSlayerBonus);
		double dragonbaneCalculation = Math.floor(slayerCalculation     * totalDragonbaneBonus);
		double sceptreCalculation    = Math.floor(dragonbaneCalculation * totalSceptreBonus);
		double accursedCalculation   = Math.floor(sceptreCalculation    * totalAccursedBonus);

		double elementalWeaknessAddition = Math.floor(baseDamageModifier * elementalWeakness);
		preHitRoll = Math.floor(accursedCalculation * totalTomeBonus) + elementalWeaknessAddition;
	}

	private void getMarkOfDarknessBonus()
	{
		// Check if using a spell
		if (activeSpell == null)
		{
			markOfDarknessBonus = 0.0;
			return;
		}

		// Mark of darkness not active
		if (!plugin.isMarkOfDarknessActive())
		{
			markOfDarknessBonus = 0.0;
			return;
		}

		// Ensures using Demonbane spell
		if (!activeSpell.getDisplayName().contains("Demonbane"))
		{
			markOfDarknessBonus = 0.0;
			return;
		}

		getDemonbaneBonus();

		// Check for Purging Staff
		if (demonbaneBonus > 0.0)
		{
			markOfDarknessBonus = 0.5;
		}
		else
		{
			markOfDarknessBonus = 0.25;
		}
	}

	@Override
	public void calculateMaxHit()
	{
		reset();
		// Base Damage Modifier
		getBaseDamageModifier();
		// Primary Magic Damage
		getPrimaryMagicDamage();
		// Pre Hit Roll == Hit Roll
		// Don't need to use the hit roll step on the wiki since we're just calculating max hit
		getPreHitRoll();
		getMarkOfDarknessBonus();
		double firstFloorCalculation = Math.floor(preHitRoll * (1 + markOfDarknessBonus));
		// Skip castle wars bonus
		// Final Post Hit Roll
		maxHit = Math.floor(firstFloorCalculation * (1 + ahrimsDamnedBonus));

		// Apply Sanguinesti passive
		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.SANGUINESTI_STAFF)
			|| EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.SANGUINESTI_STAFF_OR))
		{
			maxHit += 8.0;
		}

		applyTwinflameModifier();
	}

	private void applyTwinflameModifier()
	{
		// Twinflame Staff
		if (!EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.TWINFLAME_STAFF))
		{
			return;
		}

		if (activeSpell.getSpellbook() != Spellbook.STANDARD)
		{
			return;
		}

		for (String spell : TWINFLAME_SPELLS)
		{
			if (activeSpell.getDisplayName().contains(spell))
			{
				double secondHitDamage = Math.floor(maxHit * 0.4);
				maxHit = maxHit + secondHitDamage;
				return;
			}
		}
	}

	@Override
	public void calculateNextMaxHitRequirements()
	{
		//TODO: Implement
	}
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.NextMaxHitReqs;
import com.maxhit.PrayerType;
import com.maxhit.equipment.DemonbaneWeapon;
import com.maxhit.equipment.EquipmentFunctions;
import com.maxhit.monsters.DemonicMonsters;
import com.maxhit.monsters.MonsterFlatArmour;
import com.maxhit.sets.EquipmentSet;
import com.maxhit.styles.AttackStyle;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

public abstract class MaxHitCalculator
{
	protected final MaxHitPlugin plugin;
    protected final Client client;
    protected final ItemManager itemManager;
	protected ItemContainer equippedItems;
	@Getter
    protected Skill skill;
	protected double effectiveLevel;
	@Setter
	protected AttackStyle attackStyle;
	protected BonusCalculator bonusCalculator;
    protected double effectiveStrength;
    protected double strengthBonus;
    protected double prayerBonus;
    protected double styleBonus;
    protected double voidBonus;
	protected double avariceBonus;
	protected double salveBonus;
	protected double slayerBonus;
	protected double dragonbaneBonus;
	protected double demonbaneBonus;
	protected double flatArmour;

	@Nullable
    public Actor opponent;
	@Getter
    protected double maxHit;
	@Getter
	protected NextMaxHitReqs nextMaxHitReqs;

	@Inject
    protected MaxHitCalculator (MaxHitPlugin plugin, Client client, ItemManager itemManager, Skill skill, AttackStyle attackStyle)
    {
		this.plugin = plugin;
		this.client = client;
		this.itemManager = itemManager;
        this.skill = skill;
		this.attackStyle = attackStyle;
		this.equippedItems = client.getItemContainer(InventoryID.WORN);
		EquipmentSet.setEquippedItems(equippedItems);
		bonusCalculator = new BonusCalculator(client, skill);
        maxHit = 0.0;
        voidBonus = 1.0;
		flatArmour = 0.0;
    }

	public void setEquippedItems(ItemContainer equippedItems)
	{
		this.equippedItems = equippedItems;
		EquipmentSet.setEquippedItems(equippedItems);
	}

	protected void reset()
	{
		styleBonus = 0.0;
		prayerBonus = 1.0;
		voidBonus = 1.0;
		avariceBonus = 1.0;
		salveBonus = 1.0;
		slayerBonus = 1.0;
		dragonbaneBonus = 1.0;
		demonbaneBonus = 1.0;
		flatArmour = 0.0;
		updatePrayerBonus();
		updateEffectiveLevel();
		updateStyleBonus();
		updateVoidBonus();
	}

	protected abstract void updateStyleBonus();

	protected void updateVoidBonus()
	{
		voidBonus = bonusCalculator.getVoidBonus();
		if (skill == Skill.MAGIC)
			voidBonus -= 1.0;
	}

	protected void updateEffectiveStrength()
	{
		// getValue() gets boosted value
		effectiveStrength = Math.floor((effectiveLevel + styleBonus + 8) * voidBonus);
	}

	protected void updatePrayerBonus()
	{
		prayerBonus = bonusCalculator.getPrayerBonus();
	}

	protected void updateEffectiveLevel()
	{
		effectiveLevel = client.getBoostedSkillLevel(this.skill);

		// First Melee and Ranged Prayers always increment by at least one
		if (skill == Skill.STRENGTH)
		{
			if (PrayerType.BURST_OF_STRENGTH.isActive(client) && effectiveLevel <= 20)
			{
				effectiveLevel += 1;
				return;
			}
		}
		else if (skill == Skill.RANGED)
		{
			if (PrayerType.SHARP_EYE.isActive(client) && effectiveLevel <= 20)
			{
				effectiveLevel += 1;
				return;
			}
		}
		else if (skill == Skill.MAGIC)
		{
			// Can stop here for magic
			return;
		}

		effectiveLevel = Math.floor(effectiveLevel * prayerBonus);
	}

    protected void updateStrengthBonus()
	{
		strengthBonus = StrengthBonusCalculator.getStrengthBonus(client, equippedItems, itemManager, skill);
	}

	public int getNpcId()
	{
		if (opponent == null)
		{
			return -1;
		}

		NPC npc = (NPC) opponent;
		String npcName = npc.getName();

		if (npcName == null)
		{
			return -1;
		}

		return npc.getId();
	}

	protected void updateFlatArmour()
	{
		flatArmour = 0.0;

		int npcId = getNpcId();

		if (npcId == -1)
			return;

		for (MonsterFlatArmour monster : MonsterFlatArmour.values())
		{
			if (monster.getId() != npcId)
			{
				continue;
			}

			flatArmour = monster.getFlatArmour();
			return;
		}
	}

    public abstract void calculateMaxHit();

	public abstract void getDragonbaneBonus();

	public void getAvariceBonus()
	{
		if (!EquipmentFunctions.GetEquippedItemString(client, equippedItems, EquipmentInventorySlot.AMULET).contains(("Avarice")))
		{
			return;
		}
		NPC npc = (NPC) opponent;
		if (npc == null)
		{
			return;
		}
		String npcName = npc.getName();
		if (npcName == null)
		{
			return;
		}
		if (!npc.getName().contains("Revenant"))
		{
			return;
		}
		if (client.getVarbitValue(VarPlayerID.REVENANT_REWARD_TIME_REMAINING) > 0)
		{
			avariceBonus = 1.35;
			return;
		}
		avariceBonus = 1.2;
	}

	public void getDemonbaneBonus()
	{
		// Check if opponent is a demon
		int npcId = getNpcId();

		if (npcId == -1)
		{
			demonbaneBonus = 0.0;
			return;
		}

		if (!DemonicMonsters.ID_LIST.contains(npcId))
		{
			demonbaneBonus = 0.0;
			return;
		}

		for (DemonbaneWeapon weapon : DemonbaneWeapon.values())
		{
			// Make sure skill matches
			if (weapon.getSkill() != this.skill)
				continue;

			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, weapon.getItemId()))
			{
				demonbaneBonus = weapon.getDamageMultiplier();
				return;
			}
		}

		demonbaneBonus = 0.0;
	}

	/**
	 * Multiplies base by factor
	 * @param base base value
	 * @param factor multiplier factor
	 * @throws AssertionError if factor is less than 1.0
	 * @return Math.max(0.0, Math.floor(base * factor))
	 */
	public double factor(double base, double factor)
	{
		assert factor >= 1.0;
		return Math.max(0.0, Math.floor(base * factor));
	}

	/**
	 * Multiplies base by factor (factor must be <= 1.0)
	 * Then adds previous factor to base
	 * @param base base value
	 * @param factor multiplier factor
	 * @throws AssertionError if factor is greater than 1.0
	 * @return base + Math.floor(base * addedFactor)
	 */
	public double addFactor(double base, double factor)
	{
		assert factor <= 1.0;
		double addedFactor = Math.max(0.0, Math.floor(base * factor));
		return base + addedFactor;
	}

	protected void getSalveBonus()
	{
		salveBonus = bonusCalculator.getSalveBonus(equippedItems, opponent);
	}

	protected void getSlayerBonus() {slayerBonus = bonusCalculator.getSlayerBonus(this.plugin, equippedItems, opponent);}

	protected abstract void calculateNextMaxHitRequirements();
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.styles.AttackStyle;
import com.maxhit.styles.CombatStyle;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;

public class MaxHitCalculatorFactory
{
	private final MaxHitPlugin plugin;
    private final Client client;
    private final ItemManager itemManager;

    public MaxHitCalculatorFactory(MaxHitPlugin plugin, Client client, ItemManager itemManager)
    {
		this.plugin = plugin;
        this.client = client;
        this.itemManager = itemManager;
    }
    public MaxHitCalculator create(CombatStyle combatStyle, AttackStyle attackStyle)
    {
        if (combatStyle == CombatStyle.MELEE)
            return new MeleeMaxHitCalculator(this.plugin, this.client, this.itemManager, attackStyle);
        if (combatStyle == CombatStyle.RANGED)
            return new RangedMaxHitCalculator(this.plugin, this.client, this.itemManager, attackStyle);
        if (combatStyle == CombatStyle.MAGE)
            return new MagicMaxHitCalculator(this.plugin, this.client, this.itemManager, attackStyle);
        return  null;
    }
}

package com.maxhit.calculators;

import com.google.common.collect.ImmutableSet;
import com.maxhit.MaxHitPlugin;
