@Slf4j
public class MeleeMaxHitCalculator extends MaxHitCalculator
{
	private final Collection<Integer> FANGS = ItemVariationMapping.getVariations(ItemID.OSMUMTENS_FANG);
	private final Set<Integer> DINHS = ImmutableSet.of(ItemID.DINHS_BULWARK_ORNAMENT, ItemID.DINHS_BULWARK);
	private final DharokSet dharokSetChecker;
	private final ObsidianSet obsidianSetChecker;
	private final BerserkerNecklaceSet berserkerNecklaceSet;
	private double baseDamage;
	private double kerisBonus;
	private double golemBonus;
	private double obsidianBonus;
	private double inquisitorBonus;
	private double dharokBonus;
	private double berserkerBonus;
	private double soulReaperAxeBonus;

	protected MeleeMaxHitCalculator(MaxHitPlugin plugin, Client client, ItemManager itemManager, AttackStyle attackStyle)
	{
		super(plugin, client, itemManager, Skill.STRENGTH, attackStyle);
		dharokSetChecker = new DharokSet(client);
		obsidianSetChecker = new ObsidianSet();
		berserkerNecklaceSet = new BerserkerNecklaceSet();
		reset();
	}

	@Override
	protected void reset()
	{
		soulReaperAxeBonus = 0.0;
		updateSoulReaperAxeBonus();
		super.reset();
		baseDamage = 0.0;
		kerisBonus = 1.0;
		golemBonus = 1.0;
		obsidianBonus = 0.0;
		inquisitorBonus =  0.0;
		dharokBonus = 1.0;
		berserkerBonus = 0.0;
	}

	private void getBonuses()
	{
		getAvariceBonus();
		getSalveBonus();
		getSlayerBonus();
		getObsidianBonus();
		getDemonbaneBonus();
		getDragonbaneBonus();
		getKerisBonus();
		getInquisitorBonus();
		getGolemBonus();
		getDharokBonus();
		getBerserkerBonus();
		updateFlatArmour();
	}

	@Override
	protected void updateStyleBonus()
	{
		if (attackStyle == AttackStyle.AGGRESSIVE) {styleBonus = 3.0;}
		if (attackStyle == AttackStyle.CONTROLLED) {styleBonus = 1.0;}
	}

	private void updateSoulReaperAxeBonus()
	{
		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.SOULREAPER) ||
			EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.SOULREAPER_AXE_ORN))
		{
			int stacks = client.getVarpValue(VarPlayerID.SOULREAPER_STACKS);

			soulReaperAxeBonus = stacks * 0.06;
		}
	}

	@Override
	protected void updateEffectiveLevel()
	{
		super.updateEffectiveLevel();
		// Stacks additively
		effectiveLevel += Math.floor(effectiveLevel * soulReaperAxeBonus);
	}

	@Override
	protected void updateStrengthBonus()
	{
		super.updateStrengthBonus();
		for (int itemId : DINHS)
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, itemId))
			{
				strengthBonus += StrengthBonusCalculator.getDinhsBonus(attackStyle, equippedItems, itemManager);
				break;
			}
		}
	}

	private void getBaseDamage()
	{
		double bonusMultiplier = (strengthBonus + 64.0) / 640.0;
		baseDamage = Math.floor(0.5 + (effectiveStrength * bonusMultiplier));
	}

	private double applyBonuses(double baseDamage)
	{
		double damage = baseDamage;
		// Slayer helm and salve don't stack
		if (avariceBonus > 1.0)
		{
			damage = factor(damage, avariceBonus);
		}
		else if (salveBonus > 1.0)
		{
			damage = factor(damage, salveBonus);
		}
		else if (slayerBonus > 1.0)
		{
			damage = factor(damage, slayerBonus);
		}

		damage = addFactor(damage, demonbaneBonus);

		damage = addFactor(damage, obsidianBonus);

		damage = factor(damage, dragonbaneBonus);

		damage = factor(damage, kerisBonus);

		damage = factor(damage, golemBonus);

		// TODO add support for Rev Weapon
		// TODO add support for Leaf bladed weapons
		// TODO add support for Colossal Blade
		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.RAT_BONE_MACE))
		{
			damage = damage + 10.0;
		}

		damage = factor(damage, inquisitorBonus);

		// The Fang calculation is a bit different. Confirmed in-game
		for(int itemId : FANGS)
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, itemId))
			{
				double fangShrink = Math.floor(damage * 3.0 / 20.0);
				damage -= fangShrink;
				break;
			}
		}

		// Apply Keris chance to 3x
		if (kerisBonus > 1.0)
		{
			damage = factor(damage, 3.0);
		}

		damage = factor(damage, dharokBonus);

		damage = addFactor(damage, berserkerBonus);

		return damage;
	}

	@Override
	public void calculateMaxHit()
	{
		reset();
		getBonuses();
		updateEffectiveStrength();
		updateStrengthBonus();
		getBaseDamage();
		maxHit = applyBonuses(baseDamage);
		maxHit -= flatArmour;
		calculateNextMaxHitRequirements();
	}

	@Override
	protected void calculateNextMaxHitRequirements()
	{
		final double nextMaxHit = maxHit + 1.0;
		double tempMaxHit;
		double levelDiff = 0.0;

		// Add guard
		if (effectiveLevel < 1.0)
		{
			return;
		}
		// Get Skill level difference
		for(int i = 1; i < 26; i++)
		{
			updateEffectiveLevel();
			effectiveLevel += i;
			updateEffectiveStrength();
			updateStrengthBonus();
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;

			if (tempMaxHit >= nextMaxHit)
			{
				levelDiff = i;
				break;
			}
		};

		// Get Strength bonus difference
		double strengthBonusDiff = 0.0;
		for(int i = 1; i < 26; i++)
		{
			updateEffectiveLevel();
			updateEffectiveStrength();
			updateStrengthBonus();
			strengthBonus += i;
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;

			if (tempMaxHit >= nextMaxHit)
			{
				strengthBonusDiff = i;
				break;
			}
		};

		// Get prayer bonus difference
		double prayerDiff = 0.0;
		for(double i = 0.01; i < 0.25; i+=0.01)
		{
			updatePrayerBonus();
			prayerBonus += i;
			updateEffectiveLevel();
			updateEffectiveStrength();
			updateStrengthBonus();
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;
			if (tempMaxHit >= nextMaxHit)
			{
				prayerDiff = i;
				break;
			}
		};

		nextMaxHitReqs = new NextMaxHitReqs(skill, levelDiff, strengthBonusDiff, prayerDiff * 100.0);
	}

	public void getGolemBonus()
	{
		// Check if opponent is a golem
		int npcId = getNpcId();

		if (npcId == -1)
		{
			return;
		}

		if (!GolemMonsters.ID_LIST.contains(npcId))
		{
			return;
		}

		for (GolembaneWeapon weapon : GolembaneWeapon.values())
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, weapon.getItemId()))
			{
				golemBonus = weapon.getDamageMultiplier();
				return;
			}
		}
	}

	public void getDragonbaneBonus()
	{
		// Check if opponent is draconic
		int npcId = getNpcId();

		if (npcId == -1)
			return;

		if (!DraconicMonsters.ID_LIST.contains(npcId))
		{
			return;
		}

		// Wand is funny to me, but it does count
		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.DRAGONHUNTER_LANCE) ||
			EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.DRAGONHUNTER_WAND))
		{
			dragonbaneBonus = 1.2;
		}

	}

	private void getInquisitorBonus()
	{
		inquisitorBonus = InquisitorSet.getMultiplier(client, equippedItems);
	}

	private void getObsidianBonus()
	{
		if (obsidianSetChecker.isWearingSet())
		{
			obsidianBonus = obsidianSetChecker.getMultiplier();
		}
	}

	private void getDharokBonus()
	{
		if (dharokSetChecker.isWearingSet())
		{
			dharokBonus = dharokSetChecker.getMultiplier();
		}
	}

	private void getBerserkerBonus()
	{
		if (berserkerNecklaceSet.isWearingSet())
		{
			berserkerBonus = berserkerNecklaceSet.getMultiplier();
		}
	}

	private void getKerisBonus()
	{
		// Check if opponent is a kalphite
		int npcId = getNpcId();

		if (npcId == -1)
			return;

		if (!KalphiteMonsters.ID_LIST.contains(npcId))
		{
			return;
		}

		for (KerisWeapon weapon : KerisWeapon.values())
		{
			if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, weapon.getItemId()))
			{
				kerisBonus = weapon.getDamageMultiplier();
				return;
			}
		}
	}
}

package com.maxhit.calculators;

import com.maxhit.MaxHitPlugin;
import com.maxhit.NextMaxHitReqs;
import com.maxhit.equipment.BowAmmoRegistry;
import com.maxhit.equipment.EquipmentFunctions;
import com.maxhit.monsters.DraconicMonsters;
import com.maxhit.monsters.MagicAttribute;
import com.maxhit.styles.AttackStyle;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemVariationMapping;

@Slf4j
public class RangedMaxHitCalculator extends MaxHitCalculator
{
	private double baseDamage;
	private double crystalBonus;

	protected RangedMaxHitCalculator(MaxHitPlugin plugin, Client client, ItemManager itemManager, AttackStyle attackStyle)
	{
		super(plugin, client, itemManager, Skill.RANGED, attackStyle);
		reset();
	}

	@Override
	protected void reset()
	{
		super.reset();
		crystalBonus = 1.0;

		if (equippedItems != null)
		{
			Item weapon = this.equippedItems.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			if (weapon != null)
			{
				if (weapon.getId() == ItemID.ECLIPSE_ATLATL ||
					weapon.getId() == ItemID.HG_HUNTER_SPEAR)
				{
					this.skill = Skill.STRENGTH;
				}
			}
		}

		baseDamage = 0.0;
	}

	@Override
	protected void updateStyleBonus()
	{
		// Have to use different method since ATTACK style is just equal to RANGED
		if (client.getVarpValue(VarPlayerID.COM_MODE) == AttackStyle.ACCURATE.ordinal())
		{
			styleBonus = 3.0;
		}
	}

	private void getBaseDamage()
	{
		double strengthCalculation = (effectiveStrength * (strengthBonus + 64.0)) / 640.0;
		baseDamage = Math.floor(0.5 + strengthCalculation);
	}

	public void getDragonbaneBonus()
	{
		// Check if opponent is draconic
		int npcId = getNpcId();

		if (npcId == -1)
			return;

		if (!DraconicMonsters.ID_LIST.contains(npcId))
		{
			return;
		}

		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.DRAGONHUNTER_XBOW))
		{
			dragonbaneBonus = 1.25;
		}
	}

	private double applyBonuses(double baseDamage)
	{
		double damage = baseDamage;
		if (equippedItems == null)
		{
			return damage;
		}

		Item weaponItem = equippedItems.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());

		if (weaponItem == null)
		{
			return damage;
		}

		// Bowfa and Crystal Bow
		if (ItemVariationMapping.getVariations(ItemID.BOW_OF_FAERDHINEN_INACTIVE).contains(weaponItem.getId()) ||
			ItemVariationMapping.getVariations(ItemID.ROVING_CRYSTAL_BOW_NEW).contains(weaponItem.getId()))
		{
			Item headSlotItem = equippedItems.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
			if (headSlotItem != null &&
				ItemVariationMapping.getVariations(
					ItemVariationMapping.map(ItemID.CRYSTAL_HELMET)).contains(headSlotItem.getId()))
			{
				crystalBonus += 0.025;
			}

			Item bodySlotItem = equippedItems.getItem(EquipmentInventorySlot.BODY.getSlotIdx());
			if (bodySlotItem != null &&
				ItemVariationMapping.getVariations(
					ItemVariationMapping.map(ItemID.CRYSTAL_CHESTPLATE)).contains(bodySlotItem.getId()))
			{
				crystalBonus += 0.075;
			}

			Item legsSlotItem = equippedItems.getItem(EquipmentInventorySlot.LEGS.getSlotIdx());
			if (legsSlotItem != null &&
				ItemVariationMapping.getVariations(
					ItemVariationMapping.map(ItemID.CRYSTAL_PLATELEGS)).contains(legsSlotItem.getId()))
			{
				crystalBonus += 0.05;
			}
		}

		// Crystal bonus is applied before Amulet of Avarice/Salve/Slayer Helm(i)
		damage = factor(damage, crystalBonus);

		// Avarice, Salve, and Slayer helm don't stack
		getAvariceBonus();
		getSalveBonus();
		getSlayerBonus();
		getDragonbaneBonus();
		getDemonbaneBonus();
		if (avariceBonus > 1.0)
		{
			damage = factor(damage, avariceBonus);
		}
		else if (salveBonus > 1.0)
		{
			damage = factor(damage, salveBonus);
		}
		else if (slayerBonus > 1.0)
		{
			// Craw's bow, Dragonbane, and Demonbane are additive
			double numerator = 23;
			if (dragonbaneBonus > 1.0)
			{
				numerator += 5;
			}
			if (demonbaneBonus > 0.0)
			{
				numerator += 6;
			}

			damage = factor(damage, numerator / 20.0);
		}

		// Add Twisted Bow bonus
		damage = applyTwistedBowBonus(damage);

		// If not wearing slayer helm and not on task
		if (slayerBonus == 1.0)
		{
			damage = factor(damage, dragonbaneBonus);

			if (demonbaneBonus > 0.0)
			{
				damage = addFactor(damage, demonbaneBonus);
			}
		}

		if (EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.RAT_BONE_BOW) &&
			BowAmmoRegistry.isAmmoCompatible(weaponItem.getId(), EquipmentFunctions.GetEquippedItemId(equippedItems, EquipmentInventorySlot.AMMO)))
		{
			damage = damage + 10.0;
		}

		//TODO Add support for Craw's bow
		return damage;
	}

	@Override
	public void calculateMaxHit()
	{
		reset();
		updateEffectiveStrength();
		updateStrengthBonus();
		getBaseDamage();
		maxHit = applyBonuses(baseDamage);

		// TODO add support for special attack
		updateFlatArmour();
		maxHit -= flatArmour;

		calculateNextMaxHitRequirements();
	}

	@Override
	protected void calculateNextMaxHitRequirements()
	{
		final double nextMaxHit = maxHit + 1.0;
		double tempMaxHit;
		double levelDiff = 0.0;

		// Add guard
		if (effectiveLevel < 1.0)
		{
			return;
		}
		// Get Skill level difference
		for(int i = 1; i < 26; i++)
		{
			updateEffectiveLevel();
			effectiveLevel += i;
			updateEffectiveStrength();
			updateStrengthBonus();
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;

			if (tempMaxHit >= nextMaxHit)
			{
				levelDiff = i;
				break;
			}
		};

		// Get Strength bonus difference
		double strengthBonusDiff = 0.0;
		for(int i = 1; i < 26; i++)
		{
			updateEffectiveLevel();
			updateEffectiveStrength();
			updateStrengthBonus();
			strengthBonus += i;
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;

			if (tempMaxHit >= nextMaxHit)
			{
				strengthBonusDiff = i;
				break;
			}
		};

		// Get prayer bonus difference
		double prayerDiff = 0.0;
		for(double i = 0.01; i < 0.25; i+=0.01)
		{
			updatePrayerBonus();
			prayerBonus += i;
			updateEffectiveLevel();
			updateEffectiveStrength();
			updateStrengthBonus();
			getBaseDamage();
			tempMaxHit = applyBonuses(baseDamage);
			tempMaxHit -= flatArmour;

			if (tempMaxHit >= nextMaxHit)
			{
				prayerDiff = i;
				break;
			}
		};

		nextMaxHitReqs = new NextMaxHitReqs(skill, levelDiff, strengthBonusDiff, prayerDiff * 100.0);
	}

	private double applyTwistedBowBonus(double damage)
	{
		// Check if wearing twisted bow
		if (!EquipmentFunctions.HasEquipped(equippedItems, EquipmentInventorySlot.WEAPON, ItemID.TWISTED_BOW))
		{
			return damage;
		}

		double magicAttribute = 0;
		double cap = 250.0;

		// Check for NPC
		int npcId = getNpcId();

		if (npcId == -1)
		{
			magicAttribute = 0;
		}
		else
		{
			// Get NPCs Magic Level or Accuracy
			for(MagicAttribute attribute : MagicAttribute.values())
			{
				if (!attribute.getIds().contains(npcId))
					continue;
				magicAttribute = attribute.getAttribute();

				// If inside CoX
				if (attribute.isXerician())
				{
					cap = 350.0;
					// Scale for challenge mode
					if (client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) == 1)
						magicAttribute = magicAttribute * 1.5;
				}
				break;
			}
		}

		magicAttribute = Math.min(cap, magicAttribute);

		double eq1 = Math.floor((3.0 * magicAttribute - 14.0) / 100.0);
		double eq2 = Math.floor(3.0 * magicAttribute / 10.0);
		double eq3 = Math.floor(Math.pow((eq2 - 140.0), 2.0) / 100.0);

		// Bonus is always clamped at 250%
		double bonus = Math.min(250.0, (250.0 + eq1 - eq3));

		return Math.max(0.0, Math.floor(damage * (bonus / 100.0)));
	}
}

package com.maxhit.calculators;

import com.maxhit.equipment.EnchantedBolt;
import com.maxhit.equipment.EquipmentFunctions;
import com.maxhit.equipment.SpecialAttackWeapon;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

public class SpecialAttackCalculator
{
	private final Client client;

	private final ItemManager itemManager;
	@Setter
	private ItemContainer equippedItems;

	public SpecialAttackCalculator(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	public double getSpecialMaxHit(double maxHitBase)
	{
		Item weapon = equippedItems.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());

		if (weapon == null)
		{
			return maxHitBase;
		}

		for (SpecialAttackWeapon specialAttackWeapon : SpecialAttackWeapon.values())
		{
			if (specialAttackWeapon.getItemId() == weapon.getId())
			{
				return specialAttackWeapon.getSpecialAttackDamage(client, itemManager, equippedItems, maxHitBase);
			}
		}

		String weaponName = EquipmentFunctions.GetEquippedItemString(client, equippedItems, EquipmentInventorySlot.WEAPON);

		if (weaponName.contains("rossbo"))
		{
			int rangedLevel = client.getBoostedSkillLevel(Skill.RANGED);
			for (EnchantedBolt bolt : EnchantedBolt.values())
			{
				if (bolt.isEquipped(client, equippedItems))
				{
					return bolt.getDamageMultiplier(maxHitBase, rangedLevel);
				}
			}
		}
		return maxHitBase;
	}
}

package com.maxhit.calculators;

import com.maxhit.equipment.BowAmmoRegistry;
import com.maxhit.equipment.EquipmentFunctions;
import com.maxhit.styles.AttackStyle;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ParamID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class StrengthBonusCalculator
{

	public static double getDinhsBonus(AttackStyle attackStyle, ItemContainer equippedItems, ItemManager itemManager)
	{
		double stabBonus = 0.0;
		double slashBonus = 0.0;
		double crushBonus = 0.0;
		double rangedBonus = 0.0;

		if (equippedItems == null)
		{
			return 0.0;
		}

		// If not using Pummel, attempt to set max hit to 0
		if (attackStyle != AttackStyle.ACCURATE)
		{
			return -1000.0;
		}


		//get str bonus of worn equipment
		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			// Have to convert enum to int i.e. use ordinal
			Item item = equippedItems.getItem(slot.getSlotIdx());
			if (item == null)
			{
				continue;
			}
			int itemId = item.getId();
			final ItemStats itemStats = itemManager.getItemStats(itemId);
			if (itemStats == null)
			{
				continue;
			}
			final ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();
			stabBonus += itemEquipmentStats.getDstab();
			slashBonus += itemEquipmentStats.getDslash();
			crushBonus += itemEquipmentStats.getDcrush();
			rangedBonus += itemEquipmentStats.getDrange();
		}
		final double totalBonus = stabBonus + slashBonus + crushBonus + rangedBonus;
		return Math.max(0.0, ((totalBonus - 800.0) / 12.0) - 38.0);
	}

	public static double getStrengthBonus(Client client, ItemContainer equippedItems, ItemManager itemManager, Skill skill)
	{
		double strengthBonus = 0.0;

		if (equippedItems == null)
		{
			return strengthBonus;
		}

		// Check for quiver
		final Item cape = equippedItems.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		boolean quiverEquipped = cape != null && itemManager.getItemComposition(cape.getId()).getIntValue(ParamID.QUIVER_AMMO_AVAILABLE) == 1;
		// Base skipped ammo off quiver equipped to begin with
		boolean skipAmmo = quiverEquipped;
		boolean isSelfContainedOrLightWeapon = false;

		int bowId = -1;
		int ammoId = -1;

		// Sum all equipment strength
		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			// Check if weapon is a bow
			if (slot == EquipmentInventorySlot.WEAPON && skill == Skill.RANGED)
			{
				// Save off bow ID for checking registry later
				bowId = EquipmentFunctions.GetEquippedItemId(equippedItems, slot);

				// If it's a self-contained/charged bow, don't use ammo strength
				if (BowAmmoRegistry.isSelfContainedBow(bowId) ||
					BowAmmoRegistry.isLightWeapon(bowId))
				{
					isSelfContainedOrLightWeapon = true;
					skipAmmo = true;
				}
			}

			if (slot == EquipmentInventorySlot.AMMO)
			{
				// Save off ammo ID for checking registry later
				ammoId = EquipmentFunctions.GetEquippedItemId(equippedItems, slot);
				if (skipAmmo)
					continue;
			}

			strengthBonus += getItemStrength(skill, equippedItems, itemManager, slot);
		}

		// Quiver equipped so get strength of ammo
		if (quiverEquipped)
		{
			strengthBonus += getQuiverAmmoStrength(bowId, ammoId, client, equippedItems, itemManager);
		}

		// If ammo doesn't match, and we're not wearing a quiver, set damage to 0.0
		if (skill == Skill.RANGED)
		{

			if (!BowAmmoRegistry.isAmmoCompatible(bowId, ammoId) &&
				!quiverEquipped &&
				!isSelfContainedOrLightWeapon)
			{
				strengthBonus = -100;
			}
		}

		return strengthBonus;
	}

	public static double getItemStrength(Skill skill, ItemContainer equippedItems, ItemManager itemManager, EquipmentInventorySlot slot)
	{
		int itemId = EquipmentFunctions.GetEquippedItemId(equippedItems, slot);

		if (itemId == -1)
		{
			return 0.0;
		}

		final ItemStats itemStats = itemManager.getItemStats(itemId);

		if (itemStats == null)
		{
			return 0.0;
		}

		final ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();

		if (skill == Skill.STRENGTH)
			return itemEquipmentStats.getStr();
		if (skill == Skill.RANGED)
			return itemEquipmentStats.getRstr();
		return itemEquipmentStats.getMdmg() / 100.0;
	}

	public static double getQuiverAmmoStrength(int bowId, int ammoId, Client client, ItemContainer equippedItems, ItemManager itemManager)
	{
		final int quiverAmmoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);

		double strengthBonus = 0.0;

		// If the player has a primary ammo slot that's compatible, use it
		if (BowAmmoRegistry.isAmmoCompatible(bowId, ammoId))
		{
			strengthBonus = getItemStrength(Skill.RANGED, equippedItems, itemManager, EquipmentInventorySlot.AMMO);
		}
		else if(BowAmmoRegistry.isAmmoCompatible(bowId, quiverAmmoId))
		{
			// Otherwise, if the quiver ammo is compatible, use it
			final ItemStats itemStats = itemManager.getItemStats(quiverAmmoId);

			if (itemStats == null)
			{
				return 0.0;
			}
			final ItemEquipmentStats itemEquipmentStats = itemStats.getEquipment();

			if (itemEquipmentStats == null)
			{
				return 0.0;
			}
			else
			{
				strengthBonus = itemEquipmentStats.getRstr();
			}

		}

		return strengthBonus;
	}
}

